fmt.Errorf.example:
if err != nil {
  return fmt.Errorf("baca config: %w", err)
}

fmt.Stringer.example:
func (u User) String() string {
  return u.Name
}

fmt.GoStringer.example:
func (u User) GoString() string {
  return fmt.Sprintf("User{Name:%q}", u.Name)
}

fmt.Formatter.example:
func (m Money) Format(s fmt.State, verb rune) {
  fmt.Fprintf(s, "Rp%d", m)
}

fmt.Scanner.example:
func (id *UserID) Scan(state fmt.ScanState, verb rune) error {
  token, err := state.Token(true, nil)
  if err != nil {
    return err
  }
  *id = UserID(token)
  return nil
}
